async function searchMaps(query) {
  await tool.navigate({ tabId, url: `https://www.google.com/maps/search/${encodeURIComponent(query)}` });
  await tool.wait_for({ tabId, condition: "load_state", value: "load" });
  await tool.wait_for({ tabId, condition: "dom_settled", timeout_ms: 4000 });

  const res = await browserjs(tabId, () => {
    // Check if directly opened a place
    const h1 = document.querySelector("h1");
    const ratingEl = document.querySelector("div.F7nice");
    const addressBtn = document.querySelector("button[data-item-id='address']");
    const websiteBtn = document.querySelector("a[data-item-id='authority']");

    if (h1 && ratingEl) {
      return {
        type: "single",
        name: h1.innerText,
        ratingText: ratingEl.innerText,
        address: addressBtn ? addressBtn.innerText : null,
        website: websiteBtn ? websiteBtn.href : null,
        url: window.location.href
      };
    }

    // If list
    const items = Array.from(document.querySelectorAll("div[role='feed'] > div"));
    return {
      type: "list",
      items: items.map(el => el.innerText).filter(t => t.length > 20).slice(0, 5)
    };
  });
  return res;
}

