  { name: "Common Man Coffee Roasters Martin Road", address: "22 Martin Rd, #01-00, Singapore 239058" },
  { name: "Chye Seng Huat Hardware", address: "150 Tyrwhitt Rd, Singapore 207563" },
  { name: "Burnt Cones Sunset Way", address: "105 Clementi Street 12, #01-02, Singapore 120105" },
  { name: "Privé Keppel Bay", address: "2 Keppel Bay Vista, #01-03 Marina at Keppel Bay, Singapore 098382" },
  { name: "The Coastal Settlement", address: "200 Netheravon Rd, Singapore 508529" }
];

async function getTransitTime(origin, destination) {
  const url = `https://www.google.com/maps/dir/?api=1&origin=${encodeURIComponent(origin)}&destination=${encodeURIComponent(destination)}&travelmode=transit`;
  await tool.navigate({ tabId, url });
  await tool.wait_for({ tabId, condition: "load_state", value: "load" });
  await tool.wait_for({ tabId, condition: "dom_settled", timeout_ms: 4000 });

  const transitInfo = await browserjs(tabId, () => {
    // Look for duration elements in Google Maps directions
    // Common selectors: div[data-trip-index="0"], span.section-directions-trip-duration, div.fontHeadlineSmall, div.Fm162c
    const tripElements = document.querySelectorAll("div[data-trip-index='0'], #section-directions-trip-0, div.M77dve");
    for (const el of tripElements) {
      if (el.innerText.includes("min") || el.innerText.includes("hr")) {
        return el.innerText.split("\n").filter(t => t.trim().length > 0).slice(0, 8).join(" | ");
      }
    }
    // Fallback: search all elements with minutes
    const allDivs = Array.from(document.querySelectorAll("div, span"));
    const match = allDivs.find(d => /^\d+\s*(min|hr)/.test(d.innerText.trim()));
    if (match) {
      return match.closest("div[role='region'], div[role='listitem'], div[jsaction]")?.innerText?.split("\n").filter(t => t.trim()).slice(0, 8).join(" | ") || match.innerText;
    }
    return document.body.innerText.slice(0, 500);
  });
  return transitInfo;
}

const transitResults = [];
for (const cafe of cafes) {
  const timeInfo = await getTransitTime("Tampines MRT Station, Singapore", cafe.address);
  transitResults.push({ name: cafe.name, timeInfo });
}
console.log(JSON.stringify(transitResults, null, 2));

