const url = `https://www.google.com/maps/dir/?api=1&origin=${encodeURIComponent("Tampines MRT Station, Singapore")}&destination=${encodeURIComponent("Canopy HortPark, 33 Hyderabad Rd, Singapore 119578")}&travelmode=transit`;
