const canopyTransit = await browserjs(787783793, () => {
  const tripElements = document.querySelectorAll("div[data-trip-index='0'], #section-directions-trip-0, div.M77dve");
  for (const el of tripElements) {
    if (el.innerText.includes("min") || el.innerText.includes("hr")) {
      return el.innerText.split("\n").filter(t => t.trim().length > 0).slice(0, 8).join(" | ");
    }
  }
  return document.body.innerText.slice(0, 400);
});
console.log("Canopy HortPark transit:", canopyTransit);

