async function getSearchSnippet(query) {
  await tool.navigate({ tabId, url: `https://www.google.com/search?q=${encodeURIComponent(query)}` });
  await tool.wait_for({ tabId, condition: "load_state", value: "load" });
  return await browserjs(tabId, () => {
    return Array.from(document.querySelectorAll("div.g, div[data-sncf]")).slice(0, 3).map(el => el.innerText).join("\n---\n");
  });
}

const queries = [
  "Chye Seng Huat Hardware menu prices 2024 2025 2026",
  "Common Man Coffee Roasters menu prices Singapore Common Man Full Breakfast",
  "Wildseed Cafe Alkaff Mansion menu prices Big Pan Breakfast",
  "Tiong Bahru Bakery croissant kouign amann price Singapore 2024 2025 2026",
  "The Coastal Settlement menu prices Wagyu Beef Pizza Nasi Lemak"
];

const data = {};
for (const q of queries) {
  data[q] = await getSearchSnippet(q);
}
console.log(JSON.stringify(data, null, 2));

